add(324,'uva','he','וּבָא לְצִיּוֹן גּוֹאֵל וּלְשָׁבֵי פֶֽשַׁע בְּיַעֲקֹב נְאֻם יְיָ: וַאֲנִי זֹאת בְּרִיתִי אוֹתָם אָמַר יְיָ רוּחִי אֲשֶׁר עָלֶֽיךָ וּדְבָרַי אֲשֶׁר־שַֽׂמְתִּי בְּפִֽיךָ לֹא יָמֽוּשׁוּ מִפִּֽיךָ וּמִפִּי זַרְעֲךָ וּמִפִּי זֶֽרַע זַרְעֲךָ אָמַר יְיָ מֵעַתָּה וְעַד־עוֹלָם: וְאַתָּה קָדוֹשׁ יוֹשֵׁב תְּהִלּוֹת יִשְׂרָאֵל: וְקָרָא זֶה אֶל־זֶה וְאָמַר קָדוֹשׁ קָדוֹשׁ קָדוֹשׁ יְיָ צְבָאוֹת מְלֹא כָל־הָאָֽרֶץ כְּבוֹדוֹ: וּמְקַבְּלִין דֵּין מִן־דֵּין וְאָמְרִין קַדִּישׁ בִּשְׁמֵי מְרוֹמָא עִלָּאָה בֵּית שְׁכִינְתֵּהּ. קַדִּישׁ עַל־אַרְעָא עוֹבַד גְּבוּרְתֵּהּ. קַדִּישׁ לְעָלַם וּלְעָלְמֵי עָלְמַיָּא. יְיָ צְבָאוֹת מַלְיָא כָל־אַרְעָא זִיו יְקָרֵהּ: וַתִּשָּׂאֵֽנִי רוּחַ וָאֶשְׁמַע אַחֲרַי קוֹל רַֽעַשׁ גָּדוֹל בָּרוּךְ כְּבוֹד־יְיָ מִמְּקוֹמוֹ: וּנְטָלַֽתְנִי רוּחָא וּשְׁמָעִית בַּתְרַי קָל זִֽיעַ סַגִּיא דִּמְשַׁבְּחִין וְאָמְרִין בְּרִיךְ יְקָרָא דַּייָ מֵאֲתַר בֵּית שְׁכִינְתֵּהּ: יְיָ יִמְלֹךְ לְעוֹלָם וָעֶד: יְיָ מַלְכוּתֵהּ (קָאֵם) לְעָלַם וּלְעָלְמֵי עָלְמַיָּא. יְיָ אֱלֹהֵי אַבְרָהָם יִצְחָק וְיִשְׂרָאֵל אֲבוֹתֵֽינוּ שָׁמְרָה־זֹּאת לְעוֹלָם לְיֵֽצֶר מַחְשְׁבוֹת לְבַב עַמֶּֽךָ וְהָכֵן לְבָבָם אֵלֶֽיךָ: וְהוּא רַחוּם יְכַפֵּר עָוֹן וְלֹא יַשְׁחִית וְהִרְבָּה לְהָשִׁיב אַפּוֹ וְלֹא יָעִיר כָּל־חֲמָתוֹ: כִּי־אַתָּה אֲדֹנָי טוֹב וְסַלָּח וְרַב־חֶֽסֶד לְכָל־קֹרְאֶֽיךָ: צִדְקָתְךָ צֶֽדֶק לְעוֹלָם וְתוֹרָתְךָ אֱמֶת: תִּתֵּן אֱמֶת לְיַעֲקֹב חֶֽסֶד לְאַבְרָהָם אֲשֶׁר נִשְׁבַּֽעְתָּ לַאֲבֹתֵֽינוּ מִֽימֵי קֶֽדֶם: בָּרוּךְ אֲדֹנָי יוֹם יוֹם יַעֲמָס־לָֽנוּ הָאֵל יְשׁוּעָתֵֽנוּ סֶֽלָה: יְיָ צְבָאוֹת עִמָּֽנוּ מִשְׂגָּב־לָֽנוּ אֱלֹהֵי יַעֲקֹב סֶֽלָה: יְיָ צְבָאוֹת אַשְׁרֵי אָדָם בֹּטֵֽחַ בָּךְ: יְיָ הוֹשִֽׁיעָה הַמֶּֽלֶךְ יַעֲנֵֽנוּ בְיוֹם־קָרְאֵֽנוּ: בָּרוּךְ הוּא אֱלֹהֵֽינוּ שֶׁבְּרָאָֽנוּ לִכְבוֹדוֹ וְהִבְדִּילָֽנוּ מִן־')
add(325,'uva','he','הַתּוֹעִים וְנָֽתַן לָֽנוּ תּוֹרַת אֱמֶת וְחַיֵּי עוֹלָם נָטַע בְּתוֹכֵֽנוּ. הוּא יִפְתַּח לִבֵּֽנוּ בְּתוֹרָתוֹ וְיָשֵׂם בְּלִבֵּֽנוּ אַהֲבָתוֹ וְיִרְאָתוֹ וְלַעֲשׂוֹת רְצוֹנוֹ וּלְעָבְדוֹ בְּלֵבָב שָׁלֵם לְמַֽעַן לֹא נִיגַע לָרִיק וְלֹא נֵלֵד לַבֶּהָלָה: יְהִי רָצוֹן מִלְּפָנֶֽיךָ יְיָ אֱלֹהֵֽינוּ וֵאלֹהֵי אֲבוֹתֵֽינוּ שֶׁנִּשְׁמוֹר חֻקֶּֽיךָ בָּעוֹלָם הַזֶּה וְנִזְכֶּה וְנִחְיֶה וְנִרְאֶה וְנִירַשׁ טוֹבָה וּבְרָכָה לִשְׁנֵי יְמוֹת הַמָּשִֽׁיחַ וּלְחַיֵּי הָעוֹלָם הַבָּא: לְמַֽעַן יְזַמֶּרְךָ כָבוֹד וְלֹא יִדֹּם. יְיָ אֱלֹהַי לְעוֹלָם אוֹדֶֽךָּ: בָּרוּךְ הַגֶּֽבֶר אֲשֶׁר יִבְטַח בַּייָ וְהָיָה יְיָ מִבְטַחוֹ: בִּטְחוּ בַייָ עֲדֵי־עַד כִּי בְּיָהּ יְיָ צוּר עוֹלָמִים: וְיִבְטְחוּ בְךָ יוֹדְעֵי שְׁמֶֽךָ כִּי לֹא־עָזַֽבְתָּ דֹרְשֶֽׁיךָ יְיָ: יְיָ חָפֵץ לְמַֽעַן צִדְקוֹ יַגְדִּיל תּוֹרָה וְיַאְדִּיר:')
