add(326,'haazinu','he','הַאֲזִֽינוּ הַשָּׁמַֽיִם וַאֲדַבֵּֽרָה וְתִשְׁמַע הָאָֽרֶץ אִמְרֵי־פִי: יַעֲרֹף כַּמָּטָר לִקְחִי תִּזַּל כַּטַּל אִמְרָתִי כִּשְׂעִירִם עֲלֵי־דֶֽשֶׁא וְכִרְבִיבִים עֲלֵי־עֵֽשֶׂב: כִּי שֵׁם יְהוָֹה אֶקְרָא הָבוּ גֹֽדֶל לֵאלֹהֵֽינוּ: הַצּוּר תָּמִים פָּעֳלוֹ כִּי כָל־דְּרָכָיו מִשְׁפָּט אֵל אֱמוּנָה וְאֵין עָֽוֶל צַדִּיק וְיָשָׁר הוּא: שִׁחֵת לוֹ לֹא בָּנָיו מוּמָם דּוֹר עִקֵּשׁ וּפְתַלְתֹּל: הַֽלְיְהוָֹה תִּגְמְלוּ־זֹאת עַם נָבָל וְלֹא חָכָם הֲלוֹא־הוּא אָבִֽיךָ קָּנֶֽךָ הוּא עָשְׂךָ וַיְכֹנְנֶֽךָ: זְכֹר יְמוֹת עוֹלָם בִּֽינוּ שְׁנוֹת דֹּר־וָדֹר שְׁאַל אָבִֽיךָ וְיַגֵּדְךָ זְקֵנֶֽיךָ וְיֹאמְרוּ לָךְ: בְּהַנְחֵל עֶלְיוֹן גּוֹיִם בְּהַפְרִידוֹ בְּנֵי אָדָם יַצֵּב גְּבֻלֹת עַמִּים לְמִסְפַּר בְּנֵי יִשְׂרָאֵל: כִּי חֵֽלֶק יְהוָֹה עַמּוֹ יַעֲקֹב חֶֽבֶל נַחֲלָתוֹ: יִמְצָאֵֽהוּ בְּאֶֽרֶץ מִדְבָּר וּבְתֹֽהוּ יְלֵל יְשִׁמֹן יְסֹבְבֶֽנְהוּ יְבוֹנְנֵֽהוּ יִצְּרֶֽנְהוּ כְּאִישׁוֹן עֵינוֹ: כְּנֶֽשֶׁר יָעִיר קִנּוֹ עַל־גּוֹזָלָיו יְרַחֵף יִפְרֹשׂ כְּנָפָיו יִקָּחֵֽהוּ יִשָּׂאֵֽהוּ עַל־אֶבְרָתוֹ: יְהוָֹה בָּדָד יַנְחֶֽנּוּ וְאֵין עִמּוֹ אֵל נֵכָר:',uncertainties=['yetzrenhu exactpointing, full DivineName vowelpoints; metegs'])
